      "vocabulary": [
        {
          "id": "v1",
          "term": "Air conditioning and refrigeration (ACR) tubing",
          "definition": "ACR tubing is usually charged and sealed with gaseous nitrogen.",
          "section_id": "5.1",
          "section_title": "Types of Refrigerant Tubing",
          "page": 71,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Annealing",
          "definition": "Annealing is a process in which a substance is heated to a specific temperature range and then allowed to cool slowly.",
          "section_id": "5.1",
          "section_title": "Types of Refrigerant Tubing",
          "page": 71,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Work hardened",
          "definition": "Work hardened copper may crack at stress points when flared.",
          "section_id": "5.1",
          "section_title": "Types of Refrigerant Tubing",
          "page": 71,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "ABS (acrylonitrile-butadiene-styrene)",
          "definition": "ABS (acrylonitrile-butadiene-styrene) is a black pipe used for drainage, waste, and vent piping, as it is resistant to deposit formation.",
          "section_id": "5.2",
          "section_title": "Non-Refrigerant Tubing and Pipe",
          "page": 73,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "CPVC (chlorinated polyvinyl chloride)",
          "definition": "CPVC (chlorinated polyvinyl chloride) plastic pipe is usually a light beige or tan color.",
          "section_id": "5.2",
          "section_title": "Non-Refrigerant Tubing and Pipe",
          "page": 73,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "PVC (polyvinyl chloride)",
          "definition": "PVC is resistant to corrosion and chemical attack.",
          "section_id": "5.2",
          "section_title": "Non-Refrigerant Tubing and Pipe",
          "page": 73,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Bending spring",
          "definition": "Bending springs are used internally for making bends near the end of the tubing.",
          "section_id": "5.4",
          "section_title": "Bending Tubing",
          "page": 76,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Brazing",
          "definition": "Brazing (sometimes called silver brazing) is a process of joining metal objects by heating the objects to a temperature above 840°F (450°C) and then applying a filler metal Soldering Procedure a hook torch tip to heat all sides evenly.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 86,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Capillary action",
          "definition": "Capillary action is the movement of a liquid substance between two solid substances due to the molecular adhesive forces between the solids overcoming the liquid's cohesive forces.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 85,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Carburizing flame",
          "definition": "A carburizing flame also generates a lot of smoke.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 85,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Double flare",
          "definition": "Double flares are recommended only for larger size tubing, Procedure Before flaring, make the end of the tubing straight and square, as explained earlier in this chapter.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 79,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Flare",
          "definition": "A correctly formed flare is squeezed tightly between the flare nut and the fitting.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 78,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Flashback arrestor",
          "definition": "8-Flashback arrestors may be installed between the torch tip and the supply hoses.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 84,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Flux",
          "definition": "Flux is a paste, powder, or liquid that prevents oxide from forming on the surfaces to be soldered and aids solder flow.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 86,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Neutral flame",
          "definition": "A neutral flame is the most efficient flame in brazing.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 85,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Oxidizing flame",
          "definition": "The inner cone of an oxidizing flame is small, sharply pointed, and white.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 85,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Oxyacetylene",
          "definition": "Oxyacetylene describes a torch configuration that mixes pure oxygen and acetylene.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 83,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Purging",
          "definition": "Purging is the process of removing unwanted air, vapors, dirt, and moisture from a system by flushing them into the atmosphere with a compressed gas.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 88,
          "is_epa_608": false
        },
        {
          "id": "v19",
          "term": "Single flare",
          "definition": "Single flares are flares that are made of one layer or a single thickness of tubing.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 79,
          "is_epa_608": false
        },
        {
          "id": "v20",
          "term": "Soldering",
          "definition": "Soldering (often called soft soldering) is a process of joining metal objects by heating the objects to a temperature below 840°F (450°C) and then applying a filler metal with a melting point below 840°F (450°C).",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 85,
          "is_epa_608": false
        },
        {
          "id": "v21",
          "term": "Swaging",
          "definition": "Swaging is a common practice to reduce the use of costly fittings.",
          "section_id": "5.5",
          "section_title": "Connecting Tubing",
          "page": 89,
          "is_epa_608": false
        },
        {
          "id": "v22",
          "term": "Pipe schedule",
          "definition": "Both steel and plastic pipe are available with different wall thicknesses, called pipe schedules, which correlate to the pipe's strength.",
          "section_id": "5.6",
          "section_title": "Connecting Pipe",
          "page": 92,
          "is_epa_608": false
        },
        {
          "id": "v23",
          "term": "Solvent welding",
          "definition": "Solvent welding is the joining of two components of the same material using a solvent that temporarily dissolves the surface polymers at room temperature, allowing the polymer chains to become entangled.",
          "section_id": "5.6",
          "section_title": "Connecting Pipe",
          "page": 93,
          "is_epa_608": false
        },
        {
          "id": "v24",
          "term": "Street fitting",
          "definition": "A street fitting is an angled fitting that is male on one end and female on the other.",
          "section_id": "5.6",
          "section_title": "Connecting Pipe",
          "page": 92,
          "is_epa_608": false
        }
      ],
