      "vocabulary": [
        {
          "id": "v1",
          "term": "Adiabatic compression",
          "definition": "Adiabatic compression results in a rapid increase in temperature because the heat of compression is not lost to surrounding materials.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 115,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Atmosphere",
          "definition": "An atmosphere is approximately 14.7 pounds per square inch absolute (psia), which is frequently rounded to 15 psia.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 119,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Bar",
          "definition": "As an alternative, these gauges may have a bar scale and include an equation to calculate the kilopascal measurement (bar x 100 = kPa).",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 119,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Critical pressure",
          "definition": "The critical pressure of a substance is the pressure at which the gaseous form of the substance liquefies when the substance is at its critical temperature.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 115,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Critical temperature",
          "definition": "The critical temperature of a substance is the highest temperature at which it can be liquefied.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 115,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Heat of compression",
          "definition": "The energy added is often termed the heat of compression.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 114,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Partial vacuum",
          "definition": "A partial vacuum is any pressure below atmospheric pressure (14.7 psia).",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 117,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Pascal",
          "definition": "A pascal is a newton per square meter (N/m2 Recall that the newton is the SI unit of force.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 114,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Pascal's law",
          "definition": "Pascal's law states that pressure applied upon a confined fluid is transmitted equally and undiminished in all directions.",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 114,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Perfect vacuum",
          "definition": "A perfect vacuum is 0 pounds per square inch absolute (0 psia).",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 117,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Pressure",
          "definition": "Pressure is force per unit of area. It is expressed in pounds per square inch (psi).",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 113,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Torr",
          "definition": "The torr is a unit of measure that has been devised for measuring high vacuums (pressure close to an absolute vacuum).",
          "section_id": "7.1",
          "section_title": "Pressure",
          "page": 118,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Avogadro's law",
          "definition": "Avogadro's law can be combined with the combined gas law to create the ideal gas law.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 122,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Boyle's law",
          "definition": "Boyle's law states that the volume of a gas varies inversely to the pressure, provided the temperature remains constant.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 119,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Charles' law",
          "definition": "Charles' law states that with a constant pressure, the volume of a given quantity of gas varies directly to the absolute temperature.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 120,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Combined gas law",
          "definition": "The combined gas law states that the ratio among a gas's pressure, volume, and temperature remains constant.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 120,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Dalton's law",
          "definition": "P1 = pressure of first gas P2 = pressure of second gas +... + P N = pressure of all other gases in mixture Dalton's law is important to HVACR work because a refrigeration system should ideally contain only gas, which is the refrigerant for that system.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 122,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Gay-Lussac's law",
          "definition": "Gay-Lussac's law states that at constant volume, the absolute pressure of a given quantity of a gas varies directly with its absolute temperature.",
          "section_id": "7.2",
          "section_title": "Gas Laws",
          "page": 120,
          "is_epa_608": false
        }
      ],
