      "vocabulary": [
        {
          "id": "v1",
          "term": "High side",
          "definition": "The high side of the system is where heat is rejected out of the refrigeration system.",
          "section_id": "8.1",
          "section_title": "Compression Refrigeration Cycle",
          "page": 127,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "High-side pressure",
          "definition": "High-side pressure can also be called discharge pressure, condenser pressure, head pressure, and several other names, depending on circumstances.",
          "section_id": "8.1",
          "section_title": "Compression Refrigeration Cycle",
          "page": 127,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Low side",
          "definition": "The low side of the system is where heat is absorbed and removed from the refrigerated space.",
          "section_id": "8.1",
          "section_title": "Compression Refrigeration Cycle",
          "page": 126,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Low-side pressure",
          "definition": "Low-side pressure can also be called suction pressure, evaporator pressure, and several other names, depending on circumstances.",
          "section_id": "8.1",
          "section_title": "Compression Refrigeration Cycle",
          "page": 127,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Refrigerant",
          "definition": "In refrigeration systems, refrigerants are Ritchie Engineering Co., Inc. - YELLOW JACKET Products Division 125 fluids that absorb heat inside the refrigerated space and release the heat outside.",
          "section_id": "8.1",
          "section_title": "Compression Refrigeration Cycle",
          "page": 125,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Compressor",
          "definition": "The compressor is the\"heart\" of a compression refrigeration system.",
          "section_id": "8.2",
          "section_title": "Compression",
          "page": 127,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Reciprocating",
          "definition": "Reciprocating is a term that describes moving first in one direction and then in the opposite direction.",
          "section_id": "8.2",
          "section_title": "Compression",
          "page": 128,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Condenser",
          "definition": "A condenser is the part of a compression refrigeration system that releases heat from the vapor refrigerant and allows the vapor to condense back into liquid.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 129,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Filter-drier",
          "definition": "Liquid line filter-driers are also called high-side filter-driers.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 130,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Flash gas",
          "definition": "Flash gas is the instantaneous evaporation of some of the liquid refrigerant.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 130,
          "is_epa_608": true
        },
        {
          "id": "v11",
          "term": "Forced-air condenser",
          "definition": "A forced-air condenser uses one or more fans to disperse heat more quickly than a static condenser.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 130,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Liquid line",
          "definition": "A liquid line is tubing that carries liquid refrigerant from the condenser to the metering device.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 130,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Natural-convection condenser",
          "definition": "Condensers without fans are natural-convection condensers.",
          "section_id": "8.3",
          "section_title": "Condensing",
          "page": 129,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Metering device",
          "definition": "The metering device controls the flow of refrigerant into the evaporator.",
          "section_id": "8.4",
          "section_title": "Metering Device",
          "page": 130,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Evaporator",
          "definition": "An evaporator is a heat-exchanging device that absorbs heat into its refrigerant.",
          "section_id": "8.5",
          "section_title": "Evaporating",
          "page": 131,
          "is_epa_608": true
        },
        {
          "id": "v16",
          "term": "Forced-draft evaporator",
          "definition": "With a forced-draft evaporator, air is blown around the evaporator by a fan.",
          "section_id": "8.5",
          "section_title": "Evaporating",
          "page": 131,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Natural-draft evaporator",
          "definition": "Natural-draft evaporator reciprocating refrigerant suction line superheated The purpose of any refrigeration system is to remove heat from a space where it is not wanted.",
          "section_id": "8.5",
          "section_title": "Evaporating",
          "page": 125,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Suction line",
          "definition": "A suction line is tubing that carries refrigerant vapor from the evaporator to the compressor.",
          "section_id": "8.5",
          "section_title": "Evaporating",
          "page": 132,
          "is_epa_608": false
        },
        {
          "id": "v19",
          "term": "Superheated",
          "definition": "A refrigerant that is superheated must first decrease in temperature before it can begin to condense into a liquid.",
          "section_id": "8.5",
          "section_title": "Evaporating",
          "page": 132,
          "is_epa_608": true
        }
      ],
