      "vocabulary": [
        {
          "id": "v1",
          "term": "Apparent power",
          "definition": "The value of apparent power is always calculated in volt-amperes (VA).",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Capacitive reactance",
          "definition": "This opposition to alternating current that causes voltage to lag behind current is called capacitive reactance.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Inductance",
          "definition": "Inductance is an electrical property that opposes a change in current.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 274,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Inductive reactance",
          "definition": "This opposition to alternating current that causes current to lag behind voltage is called inductive reactance.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 274,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Power factor",
          "definition": "Power factor is the ratio of true power (a wattmeter reading) to apparent power (calculated power in volt-amperes) and is given as a percentage.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Root mean square (rms)",
          "definition": "Root mean square (rms) values are used to equate the heat produced by alternating current to direct current values that would generate the same amount of heat.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 273,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "True power",
          "definition": "To find the actual power used by a circuit, which is called the circuit's true power, take a reading with a wattmeter.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Volt-amperes (VA)",
          "definition": "The value of apparent power is always calculated in volt-amperes (VA).",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Wattmeter",
          "definition": "To find the actual power used by a circuit, which is called the circuit's true power, take a reading with a wattmeter.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 275,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Watt's law",
          "definition": "Solution: or, expressed in kilowatts, Much like Ohm's law, the power formula makes it easy to solve for any three of these variables. This formula has been called Watt's law.",
          "section_id": "14.1",
          "section_title": "Electrical Power",
          "page": 273,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "American Wire Gage (AWG)",
          "definition": "AWG is the designation most commonly used on wires.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 277,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Bonding",
          "definition": "Bonding involves joining all metallic components of an electrical system, even those that do not normally carry current, such as metallic boxes and conduit.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 282,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Circuit breaker",
          "definition": "A circuit breaker is designed to open (break) a circuit if the current passing through the circuit breaker exceeds the set limit.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 280,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Class 2 circuit",
          "definition": "Class 2 circuits are defined as circuits supplied by a power source that has an output no greater than 30 V and 1000 VA.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 277,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Fuse",
          "definition": "Fuses are typically available in either a plug or cartridge arrangement.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 280,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Ground",
          "definition": "Ground is the earth to which an electrical system connects.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 282,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Grounded conductor",
          "definition": "Grounded conductors are connected to a grounded transformer.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 282,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Ground fault circuit interrupter (GFCI)",
          "definition": "A ground fault circuit interrupter opens when the equipment connected to it is defective, misused, or improperly grounded.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 281,
          "is_epa_608": false
        },
        {
          "id": "v19",
          "term": "Grounding",
          "definition": "Grounding refers to the act of connecting something to the earth or the equipment that connects something to earth.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 282,
          "is_epa_608": false
        },
        {
          "id": "v20",
          "term": "Single-phase",
          "definition": "A single-phase voltage cycle has a single alternating current.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 276,
          "is_epa_608": false
        },
        {
          "id": "v21",
          "term": "Three-phase",
          "definition": "Threephase power is often used by commercial businesses that have a higher-voltage, three-phase transformer.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 276,
          "is_epa_608": false
        },
        {
          "id": "v22",
          "term": "Ungrounded conductor",
          "definition": "Ungrounded conductors are connected to the phase lines of a transformer.",
          "section_id": "14.2",
          "section_title": "Power Circuits",
          "page": 282,
          "is_epa_608": false
        },
        {
          "id": "v23",
          "term": "Ground fault",
          "definition": "A ground fault is a condition in which a device or ungrounded metal part becomes electrically hot or live.",
          "section_id": "14.3",
          "section_title": "Electrical Problems",
          "page": 283,
          "is_epa_608": false
        },
        {
          "id": "v24",
          "term": "Overload",
          "definition": "An overload is a condition in which too much current flows through a circuit.",
          "section_id": "14.3",
          "section_title": "Electrical Problems",
          "page": 283,
          "is_epa_608": false
        },
        {
          "id": "v25",
          "term": "Short circuit",
          "definition": "A common example of a short circuit is when noninsulated parts of conductors come into contact with each other.",
          "section_id": "14.3",
          "section_title": "Electrical Problems",
          "page": 283,
          "is_epa_608": false
        },
        {
          "id": "v26",
          "term": "Unintentional voltage drop",
          "definition": "An unintentional voltage drop is a condition in which the applied voltage from a power source is unintentionally reduced in a circuit.",
          "section_id": "14.3",
          "section_title": "Electrical Problems",
          "page": 284,
          "is_epa_608": false
        }
      ],
