      "vocabulary": [
        {
          "id": "v1",
          "term": "Low-voltage thermostat",
          "definition": "A low-voltage thermostat is a thermostat that typically operates at 24 Vac supplied by a step-down transformer.",
          "section_id": "23.2",
          "section_title": "Comfort Cooling Controls",
          "page": 479,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Power-stealing thermostat",
          "definition": "Power-stealing thermostats are electronic thermostats that draw a small amount of power from the low-voltage side of the HVAC system control to operate the thermostat electronics.",
          "section_id": "23.2",
          "section_title": "Comfort Cooling Controls",
          "page": 481,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Programmable thermostat",
          "definition": "A programmable thermostat allows an occupant to tailor indoor comfort to suit individual preference and schedule.",
          "section_id": "23.2",
          "section_title": "Comfort Cooling Controls",
          "page": 484,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Central air-conditioning system",
          "definition": "The indoor unit of a central air-conditioning system is also called the air handler.",
          "section_id": "23.3",
          "section_title": "Central Air-Conditioning Systems",
          "page": 488,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Access valve locks",
          "definition": "Another method of prevention is the installation of access valve locks.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 489,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Blank-off plates",
          "definition": "Blank-off plates are sheet metal plates that support the evaporator coil and block off areas of the plenum so that all the air passing through the plenum is directed through the evaporator coil.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 489,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "DIP switches",
          "definition": "Of importance to thermostat subbase installation are DIP switches.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 493,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Free cooling",
          "definition": "Free cooling is the use of an air-side economizer to draw in cool outdoor air to reduce indoor air temperature.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 494,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Quick-connect couplings",
          "definition": "Quick-connect couplings are discussed later in this chapter.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 491,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Wi-Fi enabled thermostat",
          "definition": "With Wi-Fi enabled thermostats, a user can operate the thermostat while away from the building.",
          "section_id": "23.4",
          "section_title": "Installing Central Air-Conditioning",
          "page": 495,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Ductless split system",
          "definition": "A ductless split system is a split air-conditioning system that does not use forced-air ductwork as a primary means of distributing cooled air.",
          "section_id": "23.6",
          "section_title": "Ductless Split Systems",
          "page": 507,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Overflow switch",
          "definition": "To avoid an overflowing drain pan, many indoor units are equipped with an overflow switch.",
          "section_id": "23.6",
          "section_title": "Ductless Split Systems",
          "page": 509,
          "is_epa_608": false
        }
      ],
