      "path": "./modules/chapters/ch27.html",
      "version": "cf94e01806",
      "updated_at_utc": "2026-11-15T15:15:57Z",
      "size_bytes": 2244240,
      "storage_key": "mrac_study_ch27_v1",
      "exam_question_count": 48,
      "study_item_count": 61,
      "match_pair_count": 10,
      "blitz_question_count": 52,
      "sim_mission_count": 7,
      "epa_608_count": 8,
      "vocab_count": 22,
      "sections": [
        {
          "id": "27.1",
          "title": "Absorption Refrigeration Systems"
        },
        {
          "id": "27.2",
          "title": "Absorption Cooling Systems"
        },
        {
          "id": "27.3",
          "title": "Absorption System Service"
        },
        {
          "id": "27.4",
          "title": "Evaporative Cooling"
        }
      ],
      "vocabulary": [
        {
          "id": "v1",
          "term": "Absorbant",
          "definition": "An absorbant is a substance that soaks up, or absorbs, a refrigerant and lowers their combined pressure.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 588,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Absorption",
          "definition": "Absorption systems were one of the first refrigerant systems to use naturally occurring compounds such as ammonia, lithium bromide, and water as refrigerants.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 587,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Affinity",
          "definition": "Substances used as absorbants must have an affinity for the substance used as the refrigerant.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 588,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Continuous-cycle absorption system",
          "definition": "A continuous-cycle absorption system is operated by the application of a limited amount of heat.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 590,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Intermittent absorption system",
          "definition": "As their name implies, intermittent absorption systems are absorption systems that operate intermittently.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 590,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Strong solution",
          "definition": "Strong solution is drawn from the bottom of the absorber toward the absorber pump (1), where it mixes with weak solution returning from the generator.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 599,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Weak solution",
          "definition": "A weak solution contains less refrigerant than a strong solution and is capable of absorbing additional refrigerant.",
          "section_id": "27.1",
          "section_title": "Absorption Refrigeration Systems",
          "page": 588,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Cogeneration",
          "definition": "The use of energy by-products from one process as the main energy source for another process is referred to as cogeneration.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 601,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Combined heat and power (CHP) plant",
          "definition": "Trigeneration i#iii-1 A power plant that produces electricity and useful steam is referred to as a cogeneration plant, or combined heat and power (CHP) plant.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 601,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Direct-fired",
          "definition": "Some commercial absorption systems are direct-fired, meaning that they are directly heated by a burner or other heating element.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 594,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Double-effect absorption system",
          "definition": "Double-effect absorption systems may use waste heat from industrial operations or solar heat for the secondary generator heat source.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 594,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Indirect-fired",
          "definition": "Other commercial absorption systems are indirect-fired, meaning that the heat that powers the system is produced somewhere outside the absorption system and then delivered to the absorption system, such as piped-in steam, hot water, or hot gas.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 594,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Lithium bromide",
          "definition": "Lithium bromide is a nontoxic, nonflammable, nonexplosive, and chemically stable salt.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 598,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Lithium bromide absorption chiller",
          "definition": "The basic design of a lithium bromide absorption chiller consists of an upper shell and a lower shell.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 598,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Single-effect absorption system",
          "definition": "A single-effect absorption system is a design in which all of the heat released in the condensation of the refrigerant is transferred to the cooling water and then dissipated to the atmosphere in the cooling tower.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 594,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Trigeneration",
          "definition": "Trigeneration i#iii-1 A power plant that produces electricity and useful steam is referred to as a cogeneration plant, or combined heat and power (CHP) plant.",
          "section_id": "27.2",
          "section_title": "Absorption Cooling Systems",
          "page": 601,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Anhydrous ammonia",
          "definition": "Anhydrous ammonia is available in 25-lb (11-kg) cylinders.",
          "section_id": "27.3",
          "section_title": "Absorption System Service",
          "page": 602,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Evaporative cooling",
          "definition": "Evaporative cooling is often used in climates with bright sunshine and low relative humidity.",
          "section_id": "27.4",
          "section_title": "Evaporative Cooling",
          "page": 604,
          "is_epa_608": false
        },
        {
          "id": "v19",
          "term": "Excelsior",
          "definition": "At one end of the greenhouse is an opening covered by a tight lattice of fibers such as excelsior (fine curled wood shavings).",
          "section_id": "27.4",
          "section_title": "Evaporative Cooling",
          "page": 604,
          "is_epa_608": false
        },
        {
          "id": "v20",
          "term": "Roof mist cooling system",
          "definition": "A roof mist cooling system can reduce the flow of solar heat from the roof into the building's interior by more than 90% during daylight hours.",
          "section_id": "27.4",
          "section_title": "Evaporative Cooling",
          "page": 605,
          "is_epa_608": false
        },
        {
          "id": "v21",
          "term": "Roof pond cooling",
          "definition": "With roof pond cooling, the entire surface of the roof remains wet and the water is replaced as it evaporates.",
          "section_id": "27.4",
          "section_title": "Evaporative Cooling",
          "page": 605,
          "is_epa_608": false
        },
        {
          "id": "v22",
          "term": "Wet roof cooling",
          "definition": "Wet roof cooling is a method of cooling indoor temperature by the evaporation of water on a building's roof.",
          "section_id": "27.4",
          "section_title": "Evaporative Cooling",
          "page": 605,
          "is_epa_608": false
        }
      ],
