      "vocabulary": [
        {
          "id": "v1",
          "term": "Electric resistance heating",
          "definition": "Electric resistance heating is the process of producing heat by conducting electricity across electric heating elements.",
          "section_id": "35.1",
          "section_title": "Principles of Electric Resistance Heating",
          "page": 832,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Electric heating element",
          "definition": "Electric heating elements are conductors through which electrical current is passed to produce heat.",
          "section_id": "35.2",
          "section_title": "Electric Heating Elements",
          "page": 832,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Open ribbon",
          "definition": "The term open ribbon describes uninsulated electric heating elements that are composed of flat strips.",
          "section_id": "35.2",
          "section_title": "Electric Heating Elements",
          "page": 832,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Open wire",
          "definition": "The term open wire describes uninsulated electric heating wires.",
          "section_id": "35.2",
          "section_title": "Electric Heating Elements",
          "page": 832,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Tubular cased wire",
          "definition": "A tubular cased wire consists of a nichrome heating element surrounded by a magnesium oxide powder and enclosed in a heat- and corrosion-resistant steel tube.",
          "section_id": "35.2",
          "section_title": "Electric Heating Elements",
          "page": 833,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Continuous load",
          "definition": "Section 426.4 of the NEC states that fixed outdoor electric deicing and snow-melting equipment is considered as a continuous load.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 840,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Direct radiant heat",
          "definition": "An example of where direct radiant heat is a viable heating option is in a large warehouse with a few small areas where employees work.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 838,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Duct heater",
          "definition": "A duct heater is an array of electric heating elements contained in a single unit that can be installed in a run of ductwork.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 835,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Electric baseboard heating unit",
          "definition": "An electric baseboard heating unit consists of an electric heating element in a casing that is mounted close to the King Electrical Mfg.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 836,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Electric furnace",
          "definition": "An electric furnace consists of a central air handler with electric heating elements that are used to warm circulating air for a conditioned space.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 833,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Electric radiant heat",
          "definition": "Electric radiant heat describes systems that use heating elements to radiate heat that primarily warms objects instead of air.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 838,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Fan heater",
          "definition": "Fan heaters are typically used as a supplementary heat source, such as building entryways.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 836,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Indirect radiant heat",
          "definition": "Since indirect radiant heat warms a surface before warming the conditioned space or occupants, it is also called swface radiant heat.",
          "section_id": "35.3",
          "section_title": "Electric Heating Systems",
          "page": 839,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Fusible link",
          "definition": "Like a bimetal disc, a fusible link is wired to turn off the electric heating elements.",
          "section_id": "35.4",
          "section_title": "Electric Furnace and Duct Heater Controls",
          "page": 844,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Mercury contactor",
          "definition": "A mercury contactor is a switching device that immerses its electrodes into a small pool of mercury for electrical contact.",
          "section_id": "35.4",
          "section_title": "Electric Furnace and Duct Heater Controls",
          "page": 844,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Sequencer",
          "definition": "A sequencer is a device that closes and opens its electrical contacts on a time delay for energizing a series of electrical loads in sequence.",
          "section_id": "35.4",
          "section_title": "Electric Furnace and Duct Heater Controls",
          "page": 841,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Line voltage",
          "definition": "In industry, line voltage is commonly considered either 120 Vac or 240 Vac.",
          "section_id": "35.5",
          "section_title": "Electric Baseboard Heating Unit Controls",
          "page": 845,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Line-voltage thermostat",
          "definition": "A line-voltage thermostat is a thermostat that typically operates using either 120 Vac or 240 Vac.",
          "section_id": "35.5",
          "section_title": "Electric Baseboard Heating Unit Controls",
          "page": 845,
          "is_epa_608": false
        }
      ],
