      "blitz_question_count": 39,
      "sim_mission_count": 7,
      "epa_608_count": 0,
      "vocab_count": 23,
      "sections": [
        {
          "id": "41.1",
          "title": "Commercial Refrigeration Applications"
        },
        {
          "id": "41.2",
          "title": "Commercial Refrigeration Systems"
        },
        {
          "id": "41.3",
          "title": "Industrial Applications"
        }
      ],
      "vocabulary": [
        {
          "id": "v1",
          "term": "Distributed system",
          "definition": "A distributed system is a unit containing multiple compressors that circulate refrigerant through the evaporators in a nearby conditioned space, such as reach-in coolers or display cases.",
          "section_id": "41.1",
          "section_title": "Commercial Refrigeration Applications",
          "page": 975,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "High-temperature refrigeration",
          "definition": "High-temperature refrigeration supplies case temperatures from 40°F to 60°F (4°C to 16°C).",
          "section_id": "41.1",
          "section_title": "Commercial Refrigeration Applications",
          "page": 974,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Low-temperature refrigeration",
          "definition": "Lowtemperature refrigeration supplies case temperatures from -10°F to 10°F (-23°C to -12°C).Medium-temperature refrigeration supplies case temperatures from 28°F to 40°F (-2°C to 4°C).",
          "section_id": "41.1",
          "section_title": "Commercial Refrigeration Applications",
          "page": 974,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Medium-temperature refrigeration",
          "definition": "Medium-temperature refrigeration items such as milk or juice are stored in display cases.",
          "section_id": "41.1",
          "section_title": "Commercial Refrigeration Applications",
          "page": 976,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Parallel compressor rack",
          "definition": "A parallel compressor rack is an arrangement of compressors piped in parallel with a common suction line, a common liquid line, and a common liquid receiver.",
          "section_id": "41.1",
          "section_title": "Commercial Refrigeration Applications",
          "page": 975,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Blast chiller",
          "definition": "Unlike standard refrigerator-freezers, quick chillers and blast chillers are designed to handle the large heat load required to cool hot, cooked food.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 985,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Blast freezer",
          "definition": "An alternative name for blast freezer is shock freezer.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 985,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Dispensing freezer",
          "definition": "Most dispensing freezers are available either in air- or water-cooled systems.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 989,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Hot and cold merchandiser",
          "definition": "The combination of both hot food holding and cold food refrigeration in one unit is called a hot and cold merchandiser.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 981,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Ice bank",
          "definition": "Older ice bank controls use a sensing bulb with two compartments divided by a membrane.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 979,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Ice machine",
          "definition": "Ice machines are refrigeration systems that automatically freeze and form water into ice and dispense it for consumer use.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 991,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Milk cooler",
          "definition": "Milk coolers are refrigeration systems that cool fresh milk to the legally required temperatures in a large tank.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 990,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Passively chilled beverage dispenser",
          "definition": "Passively chilled beverage dispensers transport syrup and water through stainless steel tubing that is surrounded by the same ice that is dispensed for individual drinks.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 986,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Quick chiller",
          "definition": "A quick chiller is a type of refrigeration system that cools hot food rapidly and uniformly without freezing the product.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 985,
          "is_epa_608": false
        },
        {
          "id": "v15",
          "term": "Self-contained water cooler",
          "definition": "A self-contained water cooler is a stand-alone water cooler that has its own water supply from a tank and does not have a drain.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 987,
          "is_epa_608": false
        },
        {
          "id": "v16",
          "term": "Tap water cooler",
          "definition": "A tap water cooler is a water cooler that has a plumbed water supply and drain connections.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 987,
          "is_epa_608": false
        },
        {
          "id": "v17",
          "term": "Ultraviolet lamp",
          "definition": "Ultraviolet lamps may also be used to help control bacteria and mold growth.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 980,
          "is_epa_608": false
        },
        {
          "id": "v18",
          "term": "Walk-in cabinet",
          "definition": "Walk-in cabinets (walk-in freezers) are also used for storing frozen foods.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 980,
          "is_epa_608": false
        },
        {
          "id": "v19",
          "term": "Water cooler",
          "definition": "Water coolers are refrigeration units designed to cool and dispense drinking water.",
          "section_id": "41.2",
          "section_title": "Commercial Refrigeration Systems",
          "page": 987,
          "is_epa_608": false
        },
        {
          "id": "v20",
          "term": "Cryogenic food freezing",
          "definition": "This turns perishable fresh food into longlasting frozen food. This process is commonly referred to as cryogenic food freezing.",
          "section_id": "41.3",
          "section_title": "Industrial Applications",
          "page": 999,
          "is_epa_608": false
        },
        {
          "id": "v21",
          "term": "Locker plant",
          "definition": "A locker plant is smaller than a processing plant and is designed to prepare, freeze, and store various food products.",
          "section_id": "41.3",
          "section_title": "Industrial Applications",
          "page": 998,
          "is_epa_608": false
        },
        {
          "id": "v22",
          "term": "Pressure dew point",
          "definition": "Pressure dew point is the temperature at which moisture condenses in pressurized air (air that is not at atmospheric pressure).",
          "section_id": "41.3",
          "section_title": "Industrial Applications",
          "page": 998,
          "is_epa_608": false
        },
        {
          "id": "v23",
          "term": "Processing plant",
          "definition": "A locker plant is smaller than a processing plant and is designed to prepare, freeze, and store various food products.",
          "section_id": "41.3",
          "section_title": "Industrial Applications",
          "page": 998,
          "is_epa_608": false
        }
      ],
