      "exam_question_count": 24,
      "study_item_count": 31,
      "match_pair_count": 10,
      "blitz_question_count": 38,
      "sim_mission_count": 7,
      "epa_608_count": 3,
      "vocab_count": 14,
      "sections": [
        {
          "id": "42.1",
          "title": "Transportation Refrigeration"
        },
        {
          "id": "42.2",
          "title": "Alternative Refrigeration Methods"
        }
      ],
      "vocabulary": [
        {
          "id": "v1",
          "term": "Eutectic plate",
          "definition": "A eutectic plate is a thin, rectangular tank containing an evaporator surrounded by a solution that freezes at a desired temperature.",
          "section_id": "42.1",
          "section_title": "Transportation Refrigeration",
          "page": 1005,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Keel cooler",
          "definition": "Unlike standard air-cooled condensers at a residence or on top of a building, keel coolers are submerged in water.",
          "section_id": "42.1",
          "section_title": "Transportation Refrigeration",
          "page": 1007,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Quench valve",
          "definition": "The quench valve is a thermostatic expansion valve (TXV) that acts as a liquid injection valve from the liquid line to the suction line.",
          "section_id": "42.1",
          "section_title": "Transportation Refrigeration",
          "page": 1003,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Standby power",
          "definition": "The refrigeration system is plugged into the electrical grid while the trailer is parked. This is referred to as standby power.",
          "section_id": "42.1",
          "section_title": "Transportation Refrigeration",
          "page": 1005,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Dry ice",
          "definition": "Dry ice is carbon dioxide (CO2 ) frozen solid. It is pressed into various sizes and shapes, typically blocks or slabs.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1009,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Peltier effect",
          "definition": "This phenomenon, called the Peltier effect, is the basis of modern thermoelectric refrigeration.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1010,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Refrigerant jet system",
          "definition": "A refrigerant jet system uses waste heat to help pressurize refrigerant and drive it from the evaporator to the condenser.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1014,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Steam jet system",
          "definition": "A steam jet system uses water as the working fluid, whereas a refrigerant jet system uses a refrigerant, such as R-1234yf.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1014,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Stirling cycle",
          "definition": "The Stirling cycle is a closed thermodynamic cycle that can convert thermal energy into mechanical energy and vice versa.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1015,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Sublimation",
          "definition": "The process of a solid changing directly into a vapor is called sublimation.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1009,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Thermoelectric couple",
          "definition": "A thermoelectric couple is formed by connecting one N-type material and one P-type material.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1010,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Thermoelectric module",
          "definition": "Thermoelectric modules are used for the cooling and heating of nuclear submarines and for controlling temperatures in electronic equipment, such as computers and aerospace devices.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1012,
          "is_epa_608": false
        },
        {
          "id": "v13",
          "term": "Thermoelectric refrigeration",
          "definition": "Thermoelectric refrigeration is the process of transferring heat energy from one place to another using the movement of electrons.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1010,
          "is_epa_608": false
        },
        {
          "id": "v14",
          "term": "Vortex tube",
          "definition": "A vortex tube is a simple device that can provide cold air by separating it from hot air.",
          "section_id": "42.2",
          "section_title": "Alternative Refrigeration Methods",
          "page": 1012,
          "is_epa_608": false
        }
      ],
