      "vocabulary": [
        {
          "id": "v1",
          "term": "Galvanic action",
          "definition": "Galvanic action is the corrosion of metal that occurs when two different metals are in contact in moist air.",
          "section_id": "47.5",
          "section_title": "Installing Refrigerant Lines",
          "page": 1150,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "High-side charging",
          "definition": "High-side charging is a method of injecting liquid refrigerant into the high side of a commercial refrigeration system through a high-side service valve, often the liquid receiver service valve (LRSV).",
          "section_id": "47.8",
          "section_title": "Charging Commercial Systems",
          "page": 1158,
          "is_epa_608": true
        },
        {
          "id": "v3",
          "term": "Low-side charging",
          "definition": "Low-side charging is a method of injecting refrigerant vapor into the low side of a commercial refrigeration system through a low-side service valve, often the suction service valve (SSV).",
          "section_id": "47.8",
          "section_title": "Charging Commercial Systems",
          "page": 1157,
          "is_epa_608": true
        },
        {
          "id": "v4",
          "term": "Mounting grommets",
          "definition": "The vibration from a running compressor is commonly and safely dampened by mounting grommets.",
          "section_id": "47.2",
          "section_title": "Installing Condensing Units",
          "page": 1145,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Ice formation",
          "definition": "For expansion valves with flared connections, a rubber seal at the end of the flare nut serves to stop ice formation.",
          "section_id": "47.3",
          "section_title": "Installing Expansion Valves",
          "page": 1147,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Solenoid valves",
          "definition": "The solenoid valves allow each evaporator to be isolated from the rest of the system.",
          "section_id": "47.3",
          "section_title": "Installing Expansion Valves",
          "page": 1148,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Brackets",
          "definition": "These stands or brackets are adjustable to allow the technician to level the evaporator in all directions.",
          "section_id": "47.4",
          "section_title": "Installing Evaporators",
          "page": 1149,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Traps",
          "definition": "In these instances, traps are used in the compressor discharge line.",
          "section_id": "47.5",
          "section_title": "Installing Refrigerant Lines",
          "page": 1146,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Evaporator outlet",
          "definition": "An evaporator pressure regulator should be connected between the evaporator outlet and the suction line manifold.",
          "section_id": "47.9",
          "section_title": "Starting a Commercial Refrigeration System",
          "page": 1149,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Manifold",
          "definition": "In the other method, manifolds are used to bring the various lines to a centralized point.",
          "section_id": "47.5",
          "section_title": "Installing Refrigerant Lines",
          "page": 1151,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Metering devices",
          "definition": "The one component that should be located between a filter-drier and a refrigerant metering device is a sight glass.",
          "section_id": "47.5",
          "section_title": "Installing Refrigerant Lines",
          "page": 1154,
          "is_epa_608": false
        },
        {
          "id": "v12",
          "term": "Liquid line",
          "definition": "The liquid line manifold, which may be located on a wall near the condensing unit, distributes refrigerant from a single liquid line to separate metering devices and their corresponding evaporators.",
          "section_id": "47.4",
          "section_title": "Installing Evaporators",
          "page": 1151,
          "is_epa_608": false
        }
      ],
