      "vocabulary": [
        {
          "id": "v1",
          "term": "Wear gauge",
          "definition": "A wear gauge will help in determining a sheave's condition.",
          "section_id": "49.2",
          "section_title": "Checking Electrical Circuits, Motors, and Compressors",
          "page": 1208,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Condenser capacity",
          "definition": "Condenser capacity is the amount of heat a condenser can reject.",
          "section_id": "49.3",
          "section_title": "Checking Condensers",
          "page": 1213,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Water hammer",
          "definition": "A noisy condition that is easily recognized is water hammer, which is a single, distinct thump (rap) heard in the pipes just as a valve closes.",
          "section_id": "49.3",
          "section_title": "Checking Condensers",
          "page": 1219,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Suction line pressure drop",
          "definition": "Suction line pressure drop should not be excessive.",
          "section_id": "49.5",
          "section_title": "Checking Refrigerant Lines",
          "page": 1221,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Temperature survey",
          "definition": "A quick way of locating possible unintentional pressure drops along a liquid line is by performing a temperature survey.",
          "section_id": "49.5",
          "section_title": "Checking Refrigerant Lines",
          "page": 1220,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Ohmmeter",
          "definition": "An ohmmeter is often used to check continuity in these de-energized circuits.",
          "section_id": "49.2",
          "section_title": "Checking Electrical Circuits, Motors, and Compressors",
          "page": 1213,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Starting capacitor",
          "definition": "If a motor hums but will not start, check the starting capacitor.",
          "section_id": "49.2",
          "section_title": "Checking Electrical Circuits, Motors, and Compressors",
          "page": 1206,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Capacitor tester",
          "definition": "Motor capacitors should be checked with a capacitor tester.",
          "section_id": "49.5",
          "section_title": "Checking Refrigerant Lines",
          "page": 1213,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Low, steady hum",
          "definition": "A motor will make a low, steady hum, under normal conditions.",
          "section_id": "49.1",
          "section_title": "General Inspection Overview",
          "page": 0,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Sharp clicking noise",
          "definition": "Faulty valves may be detected by a sharp clicking noise in the compressor as it operates.",
          "section_id": "49.6",
          "section_title": "Checking Refrigerant Valves",
          "page": 1208,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "Lower than normal",
          "definition": "Tony attaches his gauge manifold and finds that the suction pressure is higher than normal and the discharge pressure is lower than normal.",
          "section_id": "49.5",
          "section_title": "Checking Refrigerant Lines",
          "page": 1212,
          "is_epa_608": true
        },
        {
          "id": "v12",
          "term": "Chlorine-based solution",
          "definition": "If bacteria is present, the coils must be disinfected with a chlorine-based solution to kill off bacteria.",
          "section_id": "49.3",
          "section_title": "Checking Condensers",
          "page": 1217,
          "is_epa_608": false
        }
      ],
