      "vocabulary": [
        {
          "id": "v1",
          "term": "Atmospheric balancing",
          "definition": "Atmospheric balancing prevents air and particles from rushing into the system when opened.",
          "section_id": "50.1",
          "section_title": "System Service Fundamentals",
          "page": 1231,
          "is_epa_608": false
        },
        {
          "id": "v2",
          "term": "Jumpered",
          "definition": "There may be different safety controls that need to be jumpered to prevent them from cycling off the system.",
          "section_id": "50.1",
          "section_title": "System Service Fundamentals",
          "page": 1233,
          "is_epa_608": false
        },
        {
          "id": "v3",
          "term": "Burnout filter-drier",
          "definition": "Burnout filter-driers are designed for use after burnouts.",
          "section_id": "50.2",
          "section_title": "Servicing Motors and Compressors",
          "page": 1237,
          "is_epa_608": false
        },
        {
          "id": "v4",
          "term": "Fin comb",
          "definition": "Fin combs are used to straighten condenser and evaporator fins.",
          "section_id": "50.3",
          "section_title": "Servicing Condensers",
          "page": 1241,
          "is_epa_608": false
        },
        {
          "id": "v5",
          "term": "Flywheel",
          "definition": "The flywheel can be removed with a universal flywheel puller.",
          "section_id": "50.2",
          "section_title": "Servicing Motors and Compressors",
          "page": 1236,
          "is_epa_608": false
        },
        {
          "id": "v6",
          "term": "Refrigerant oil",
          "definition": "Remember that refrigerant oil and all the oil transfer equipment must be clean and dry.",
          "section_id": "50.2",
          "section_title": "Servicing Motors and Compressors",
          "page": 1238,
          "is_epa_608": false
        },
        {
          "id": "v7",
          "term": "Outside diameter",
          "definition": "To differentiate from plumbing and other types of piping in nominal sizes, ACR tubing size is designated by the actual outside diameter of the tubing.",
          "section_id": "50.3",
          "section_title": "Servicing Condensers",
          "page": 1245,
          "is_epa_608": false
        },
        {
          "id": "v8",
          "term": "Liquid receiver",
          "definition": "Large liquid receivers are equipped with safety release valves.",
          "section_id": "50.4",
          "section_title": "Servicing Liquid Lines",
          "page": 1242,
          "is_epa_608": false
        },
        {
          "id": "v9",
          "term": "Open-drive",
          "definition": "Motors used on open-drive compressors in commercial systems vary in size.",
          "section_id": "50.2",
          "section_title": "Servicing Motors and Compressors",
          "page": 1236,
          "is_epa_608": false
        },
        {
          "id": "v10",
          "term": "Hermetic",
          "definition": "The warmest spot in a hermetic compressor is usually the motor windings due to high current draw.",
          "section_id": "50.4",
          "section_title": "Servicing Liquid Lines",
          "page": 1237,
          "is_epa_608": false
        },
        {
          "id": "v11",
          "term": "TXV",
          "definition": "A TXV's sensing bulb should be secured to the suction line tubing.",
          "section_id": "50.6",
          "section_title": "Servicing Valves",
          "page": 1248,
          "is_epa_608": true
        },
        {
          "id": "v12",
          "term": "Air-cooled",
          "definition": "Most air-cooled condensers are housed in a protective shroud.",
          "section_id": "50.3",
          "section_title": "Servicing Condensers",
          "page": 1240,
          "is_epa_608": false
        }
      ],
